def is_sorter(n, net):
    nv = 1 << n
    R = (1 << nv) - 1
    masks = {}
    for a in range(n):
        for b in range(a+1, n):
            hi = 0
            for v in range(nv):
                if ((v >> a) & 1) and not ((v >> b) & 1):
                    hi |= 1 << v
            masks[(a,b)] = (hi, (1<<b) - (1<<a))
    for a,b in net:
        hi, d = masks[(a,b)]
        hit = R & hi
        R = (R & ~hi) | (hit << d)
    target = 0
    for k in range(n+1):
        v = 0
        for c in range(k, n):
            v |= 1 << c
        target |= 1 << v
    return R == target

